    { double *restrict d = dst + ((long)j0*23 + j1)*46;
      for(int t=0;t<5;++t) STU(d+t*8, rowbuf[t]);
      _mm512_mask_storeu_pd(d+40, (__mmask8)63, (__m512d)rowbuf[5]); }
